sql_query:
SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Included in MA" = 'Yes' AND "Monotherapy/combination" = 'Combination' AND "Name of ICI" = 'Atezolizumab' AND "Type of combination" = 'ICI+Chemo';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Treatment regimen" AS source_value FROM clinical_trials WHERE "Included in MA" = 'Yes' AND "Monotherapy/combination" = 'Combination' AND "Name of ICI" = 'Atezolizumab' AND "Type of combination" = 'ICI+Chemo'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_added_agents(source_value) AS "added_agents"
FROM base;
